import unittest
import json
from encode import dumps_event
from decode import loads_event
class Contract(unittest.TestCase):
    def test_keys(self): self.assertEqual(set(json.loads(dumps_event("a", {}))), {"event_id", "payload"})
    def test_decode(self): self.assertEqual(loads_event('{"event_id":"a","payload":{"n":1}}')["payload"], {"n":1})
    def test_roundtrip(self): self.assertEqual(loads_event(dumps_event("a", {"文字":"值"})), {"event_id":"a","payload":{"文字":"值"}})
    def test_invalid(self):
        for value in ["[]", '{"event_id":"a","payload":[]}', '{"event_id":"a","payload":{},"extra":1}']:
            with self.assertRaises(ValueError): loads_event(value)

