import json
def dumps_event(event_id, payload):
    return json.dumps({"event_id": event_id, "payload": payload}, ensure_ascii=False)

import json
def loads_event(text):
    data = json.loads(text)
    if not isinstance(data, dict) or set(data) != {"event_id", "payload"} or not isinstance(data["payload"], dict):
        raise ValueError("invalid event")
    return data
